mapper.select:
select
count(*)
from
med_exam_package ep


        and ep.package_name like concat('%', #{packageName}, '%')


        and ep.package_code = #{packageCode}


        and ep.package_type = #{packageType}


        and ep.category_id = #{categoryId}


        and ep.status = #{status}

select ep.id, ep.package_name as packageName, ep.package_code as packageCode, ep.original_price as originalPrice, ep.current_price as currentPrice, ep.sales_volume as salesVolume, ep.package_type as packageType, pr.rule_name as ruleName, (ep.exam_items is not null) as hasDocument, ep.status, ep.category_id as categoryId from med_exam_package ep left join promotion_rule pr on ep.promotion_id = pr.rule_id
and ep.package_name like concat('%', #{packageName}, '%')
and ep.package_code = #{packageCode}
and ep.package_type = #{packageType}
and ep.category_id = #{categoryId}
and ep.status = #{status}
order by ep.id asc limit #{startIndex}, #{pageSize}

mapper.update:
update med_exam_package
set exam_items = #{examItems},
    md5_hash=#{md5Hash}
where id = #{id}

update med_exam_package
set status = #{status}
where id = #{id}
